const fs=require("node:fs"),path=require("node:path");
const {JSDOM}=require("jsdom");
const markup=fs.readFileSync("dist/index.html","utf8");
const dom=new JSDOM(markup,{url:"http://localhost/",runScripts:"outside-only",pretendToBeVisual:true});
const win=dom.window;
const out=require("esbuild").buildSync({entryPoints:["dist/index.js"],bundle:true,write:false,format:"iife",globalName:"MintModule",platform:"browser"});
win.eval(out.outputFiles[0].text+"\nMintModule.default();");
setTimeout(()=>{
 const p=[...win.document.querySelectorAll("p")].find(n=>n.textContent.trim()==="Hello, World!");
 if(!p){console.error(win.document.body.innerHTML);process.exit(2);}
 console.log(p.textContent.trim());dom.window.close();
},500);
